def D(id, title, lead, marche, visuel, question, comps, prediction=False, demonstration=None):
    return {"id": id, "title": title, "lead": lead, "marche": marche, "visuel": visuel, "question": question,
            "prediction": prediction, "competences": comps, "demonstration": demonstration or []}


